import{f as r,c as t,o as e,a5 as l}from"./chunks/framework.BsEAYNxL.js";const m=JSON.parse('{"title":"AI 编年史 05：多模态 (Multimodal) 的感官觉醒","description":"","frontmatter":{"title":"AI 编年史 05：多模态 (Multimodal) 的感官觉醒","date":"2026-02-14T00:00:00.000Z","categories":["AI","Tech History"],"tags":["Multimodal","Vision","Audio","LLaVA","Gemini","GPT-4o","Chronicle"],"ai_role":"writer","reading_stats":{"count":915,"minutes":3}},"headers":[],"relativePath":"ai-chronicles/06-multimodal.md","filePath":"ai-chronicles/06-multimodal.md","lastUpdated":null}'),i={name:"ai-chronicles/06-multimodal.md"};function o(n,a,s,g,u,h){return e(),t("div",null,[...a[0]||(a[0]=[l('<h2 id="_0-核心工程直觉-对齐与投影" tabindex="-1">0. 核心工程直觉：对齐与投影 <a class="header-anchor" href="#_0-核心工程直觉-对齐与投影" aria-label="Permalink to &quot;0. 核心工程直觉：对齐与投影&quot;">​</a></h2><p>多模态的本质，是<strong>把不同维度的信号（像素、波形）映射到同一个语义空间（向量）里</strong>。</p><ul><li><strong>对齐 (Alignment)</strong>：让“猫的图片向量”和“猫的文字向量”在空间中尽量靠近。</li><li><strong>投影 (Projection)</strong>：把一种模态的向量“翻译”成另一种模态能理解的格式。</li></ul><h2 id="第一阶段-分治时代-——-各司其职-pre-2021" tabindex="-1">第一阶段：分治时代 —— 各司其职 (Pre-2021) <a class="header-anchor" href="#第一阶段-分治时代-——-各司其职-pre-2021" aria-label="Permalink to &quot;第一阶段：分治时代 —— 各司其职 (Pre-2021)&quot;">​</a></h2><p>在多模态大一统之前，视觉、听觉、语言是三个独立的王国。</p><h3 id="_1-1-背景与痛点" tabindex="-1">1.1 背景与痛点 <a class="header-anchor" href="#_1-1-背景与痛点" aria-label="Permalink to &quot;1.1 背景与痛点&quot;">​</a></h3><ul><li><strong>Vision (CV)</strong>：ResNet 负责分类，YOLO 负责检测，Mask R-CNN 负责分割。</li><li><strong>Audio (ASR/TTS)</strong>：Kaldi 做语音识别，WaveNet 做语音合成。</li><li><strong>Language (NLP)</strong>：BERT/GPT 做理解生成。</li><li><strong>问题</strong>：无法进行跨模态交互。比如无法问：“这张图里的猫在干什么？”</li></ul><h3 id="_1-2-关键技术" tabindex="-1">1.2 关键技术 <a class="header-anchor" href="#_1-2-关键技术" aria-label="Permalink to &quot;1.2 关键技术&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/1411.4555" target="_blank" rel="noreferrer">Show and Tell (2015)</a></strong>：Image Captioning 的开山之作。CNN 提取图像特征 -&gt; RNN 生成描述。虽然简陋，但证明了“图文互通”的可行性。</li><li><strong>VQA (Visual Question Answering)</strong>：视觉问答任务，倒逼模型去理解图像内容。</li></ul><h2 id="第二阶段-clip-的桥梁-——-对齐一切-2021-2022" tabindex="-1">第二阶段：CLIP 的桥梁 —— 对齐一切 (2021 - 2022) <a class="header-anchor" href="#第二阶段-clip-的桥梁-——-对齐一切-2021-2022" aria-label="Permalink to &quot;第二阶段：CLIP 的桥梁 —— 对齐一切 (2021 - 2022)&quot;">​</a></h2><p>OpenAI 发布的 <strong><a href="https://arxiv.org/abs/2103.00020" target="_blank" rel="noreferrer">CLIP</a></strong> (Contrastive Language-Image Pre-training) 是里程碑。</p><h3 id="_2-1-核心思想" tabindex="-1">2.1 核心思想 <a class="header-anchor" href="#_2-1-核心思想" aria-label="Permalink to &quot;2.1 核心思想&quot;">​</a></h3><ul><li><strong>对比学习 (Contrastive Learning)</strong>：把图片和对应的文字描述拉到同一个向量空间。 <ul><li>正样本：图片A + 描述A (距离近)</li><li>负样本：图片A + 描述B (距离远)</li></ul></li><li><strong>Zero-Shot</strong>：CLIP 从未见过“斑马”，但它知道“斑马”的文字向量和图片的斑马很像，所以能认出来。</li><li><strong>意义</strong>：打通了视觉与语言的语义鸿沟。DALL-E, Stable Diffusion 都离不开它。</li></ul><h2 id="第三阶段-llava-与-blip-——-给-llm-装上眼睛-2023" tabindex="-1">第三阶段：LLaVA 与 BLIP —— 给 LLM 装上眼睛 (2023) <a class="header-anchor" href="#第三阶段-llava-与-blip-——-给-llm-装上眼睛-2023" aria-label="Permalink to &quot;第三阶段：LLaVA 与 BLIP —— 给 LLM 装上眼睛 (2023)&quot;">​</a></h2><p>既然 LLM (Large Language Model) 这么聪明，能不能直接让它看图？</p><h3 id="_3-1-核心思想" tabindex="-1">3.1 核心思想 <a class="header-anchor" href="#_3-1-核心思想" aria-label="Permalink to &quot;3.1 核心思想&quot;">​</a></h3><ul><li><strong>Visual Encoder + LLM</strong>： <ul><li>用一个训练好的视觉编码器 (如 CLIP-ViT) 提取图片特征。</li><li>通过一个<strong>投影层 (Projection Layer)</strong>，把视觉特征转换成 LLM 能看懂的 Token Embedding。</li><li>LLM 以为自己在读一段“外星文字”（其实是图片特征），然后结合 Prompt 进行回答。</li></ul></li><li><strong>代表模型</strong>： <ul><li><strong><a href="https://arxiv.org/abs/2304.08485" target="_blank" rel="noreferrer">LLaVA (Large Language and Vision Assistant, 2023)</a></strong>：开源界的扛把子。基于 Vicuna，效果惊人。</li><li><strong><a href="https://arxiv.org/abs/2301.12597" target="_blank" rel="noreferrer">BLIP-2 (Salesforce, 2023)</a></strong>：引入 Q-Former 连接视觉与语言，计算效率更高。</li><li><strong><a href="https://arxiv.org/abs/2304.10592" target="_blank" rel="noreferrer">MiniGPT-4</a></strong>：证明了只训练一个投影层就能让 LLM 看图。</li></ul></li></ul><h2 id="第四阶段-native-multimodal-——-原生融合-2024-future" tabindex="-1">第四阶段：Native Multimodal —— 原生融合 (2024 - Future) <a class="header-anchor" href="#第四阶段-native-multimodal-——-原生融合-2024-future" aria-label="Permalink to &quot;第四阶段：Native Multimodal —— 原生融合 (2024 - Future)&quot;">​</a></h2><p>真正的多模态不应该是“拼凑”的，而应该是“原生”的。</p><h3 id="_4-1-背景与痛点" tabindex="-1">4.1 背景与痛点 <a class="header-anchor" href="#_4-1-背景与痛点" aria-label="Permalink to &quot;4.1 背景与痛点&quot;">​</a></h3><ul><li><strong>LLaVA 模式的问题</strong>：视觉编码器和 LLM 是分开训练的，只是强行对齐。对于细粒度任务（如数数、OCR）效果一般。</li><li><strong>音频/视频缺失</strong>：大部分只支持图文，不支持声音和视频流。</li></ul><h3 id="_4-2-解决方案-原生多模态-native-lmm" tabindex="-1">4.2 解决方案：原生多模态 (Native LMM) <a class="header-anchor" href="#_4-2-解决方案-原生多模态-native-lmm" aria-label="Permalink to &quot;4.2 解决方案：原生多模态 (Native LMM)&quot;">​</a></h3><ul><li><strong><a href="https://openai.com/index/hello-gpt-4o/" target="_blank" rel="noreferrer">GPT-4o (Omni, 2024)</a></strong>： <ul><li><strong>端到端 (End-to-End)</strong>：一个模型同时接受文本、音频、图像输入，输出也是文本、音频、图像。</li><li><strong>实时性</strong>：响应延迟极低，甚至能打断对话，模拟人类的情绪。</li><li><strong>不再需要 STT/TTS</strong>：不需要先转文字再处理，而是直接处理音频 Token，保留了语气、情感信息。</li></ul></li><li><strong><a href="https://blog.google/technology/ai/google-gemini-next-generation-model-february-2024/" target="_blank" rel="noreferrer">Gemini 1.5 Pro (Google)</a></strong>： <ul><li><strong>超长上下文</strong>：支持 1M+ tokens，可以直接输入 1 小时视频进行问答。</li><li><strong>任意模态</strong>：代码库、视频、音频、文档，统统扔进去。</li></ul></li></ul><h3 id="_4-3-总结" tabindex="-1">4.3 总结 <a class="header-anchor" href="#_4-3-总结" aria-label="Permalink to &quot;4.3 总结&quot;">​</a></h3><p>多模态是 AI 走向物理世界的最后一块拼图。未来的 AI 将不再是屏幕里的 Chatbot，而是能看懂你的手势、听懂你的语气、甚至操作机械臂的<strong>具身智能 (Embodied AI)</strong>。</p>',25)])])}const c=r(i,[["render",o]]);export{m as __pageData,c as default};
